# Let me try a stricter X-center detection: require exactly 4 neighbors with value 3
def solve_strict(grid):
    """
    Strict detection: an X-center has exactly 4 neighbors with value 3.
    Also require that the X-center value != 3.
    """
    x_centers = []
    for r in range(1, len(grid)-1):
        for c in range(1, len(grid[r])-1):
            if grid[r][c] == 0:  # Exclude background
                neighbors = [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]
                count_3 = sum(1 for nr, nc in neighbors if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 3)
                if count_3 == 4:
                    x_centers.append((r, c, grid[r][c]))
    return x_centers, grid

