def debug_fill(grid):
    x_centers = []
    for r in range(1, len(grid)-1):
        for c in range(1, len(grid[r])-1):
            if grid[r][c] != 0:
                neighbors = [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]
                count_3 = sum(1 for nr, nc in neighbors if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 3)
                if count_3 == 4:
                    x_centers.append((r, c, grid[r][c]))

    print(f"X-centers: {x_centers}")

    if not x_centers:
        return

    # Bounding box with 1-cell expansion
    min_r = max(min(xc[0] for xc in x_centers) - 1, 0)
    max_r = min(max(xc[0] for xc in x_centers) + 1, len(grid) - 1)
    min_c = max(min(xc[1] for xc in x_centers) - 1, 0)
    max_c = min(max(xc[1] for xc in x_centers) + 1, len(grid[0]) - 1)

    print(f"Bounding box: rows {min_r}-{max_r}, cols {min_c}-{max_c}")

    fill_color = max(xc[2] for xc in x_centers)
    print(f"Fill color: {fill_color}")

    # Find cells to preserve
    non_bg = set((r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != 0)

    print(f"\nX-centers and their non-bg cells (including arms):")
