def solve_fill_all(grid):
    """Fill all empty cells (0) with max non-zero color"""
    non_bg = set((r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != 0)

    # Find max non-zero color (excluding 3 which is the X-arm color?)
    colors = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v != 0 and v != 3:
                colors.append(v)

    fill_color = max(colors) if colors else 0

    print(f"Fill color: {fill_color}")

    out = [row[:] for row in grid]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if (r, c) not in non_bg:
