# Let me expand the bounding box to include all X-arms
def solve_with_arm_expansion(grid):
    # First find X-centers
    x_centers = []
    for r in range(1, len(grid)-1):
        for c in range(1, len(grid[r])-1):
            if grid[r][c] != 0:
                neighbors = [(r-1,c), (r+1,c), (r,c-1), (r,c+1)]
                count_3 = sum(1 for nr, nc in neighbors if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == 3)
                if count_3 == 4:
                    x_centers.append((r, c, grid[r][c]))

    if not x_centers:
        return [row[:] for row in grid]

    # Include X-arms in bounding box calculation
    all_x_cells = set()
    for xr, xc_r, val in x_centers:
        all_x_cells.add((xr, xc_r))  # X-center
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            all_x_cells.add((xr + dr, xc_r + dc))  # arms

    min_r = min(r for r, c in all_x_cells)
    max_r = max(r for r, c in all_x_cells)
    min_c = min(c for r, c in all_x_cells)
    max_c = max(c for r, c in all_x_cells)

    fill_color = max(xc[2] for xc in x_centers)
    non_bg = set((r, c) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] != 0)

    out = [row[:] for row in grid]
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if (r, c) not in non_bg:
                out[r][c] = fill_color

    return out

